package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strconv"
)

func funkyNumbers(n int) string {
	funkyNumber := "NO"

	maxTriangle := maxTrianglePossible(n)

	for i := maxTriangle; i > 0; i-- {
		firstTriangle := triangleNumbers(i)
		rem := n - firstTriangle

		if rem == 0 {
			continue
		}

		secFactor := maxTrianglePossible(rem)
		secTriangle := triangleNumbers(secFactor)

		triangles := firstTriangle + secTriangle

		if triangles == n {
			funkyNumber = "YES"
			break
		}
	}

	return funkyNumber
}

func maxTrianglePossible(n int) int {
	// k(k+1) / 2 = n where n is an integer
	// k(k+1) = n*2
	// k^2 + k - n*2 = 0 -> factors

	k := int(math.Floor(math.Sqrt(float64(n * 2))))

	return k
}

func triangleNumbers(x int) int {
	f := (x * (x + 1)) / 2

	return f
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	if scanner.Scan() {
		input := scanner.Text()
		n, err := strconv.Atoi(input)
		if err != nil {
			return
		}
		res := funkyNumbers(n)
		fmt.Println(res)
	}
}
